                    [-10, -5, 0, 5, 10].forEach(eta => { const y = AC.Cm0 - Kn * AC.CLa * (16 * DEG - AC.alpha0) + AC.Cme * eta * DEG; if (Math.abs(y) < 0.46) label(ctx, `η=${eta > 0 ? '+' : eta < 0 ? '−' : ''}${Math.abs(eta)}°`, X(16) - 4, Y(y) - 9, etaColors[eta], 'right', 9); });
