            under: [(X, Y) => { ctx.fillStyle = 'rgba(248,113,113,0.08)'; ctx.fillRect(X(0), Y(yr[1]), X(xr[1]) - X(0), Y(yr[0]) - Y(yr[1])); label(ctx, 'UNSTABLE', X(xr[1]) - 6, Y(yr[1]) + 12, 'rgba(248,113,113,0.7)', 'right', 9); label(ctx, 'STABLE', X(xr[0]) + 6, Y(yr[1]) + 12, 'rgba(52,211,153,0.7)', 'left', 9); }],
